svg.script:
(function () {
  var state = {nA:0, xA:0, nB:0, xB:0, sig:false};
  var barA = document.getElementById('barA'), barB = document.getElementById('barB');
  var valA = document.getElementById('valA'), valB = document.getElementById('valB');
  var pval = document.getElementById('pval'), btnLabel = document.getElementById('btnLabel');
  var btn = document.getElementById('btn');
  var statusT = document.getElementById('status'), hint = document.getElementById('hint'), cta = document.getElementById('cta');
  var started = false;

  // —— retention + contact (shared pattern) ——
  var GAME = 'abtest', DAILY_TARGET = 12;
  var DAILY_GAMES = ['snake', '2048', 'pong', 'abtest', 'funnel', 'cohort', 'sql', 'metric', 'retention', 'bottleneck'];
  var LS_BEST = 'arcade_best_' + GAME;
  var IS_LOCAL = /^(localhost|127\.0\.0\.1|::1|0\.0\.0\.0)$/.test(window.location.hostname);
  var PH_KEY = 'phc_tdju2w288PnkFE2e96efWKpoCvBPHPtveSztZK9NnGrv';
  if (!IS_LOCAL && PH_KEY.indexOf('__PH_') !== 0 && !window.posthog) {
    try {
      var phs = document.createElementNS('http://www.w3.org/2000/svg', 'script');
      phs.setAttribute('href', 'https://us-assets.i.posthog.com/static/array.js');
      phs.setAttribute('type', 'text/javascript');
      phs.onload = function () { try { window.posthog.init(PH_KEY, { defaults: '2026-05-30', persistence: 'localStorage+cookie', api_host: 'https://us.i.posthog.com', capture_pageview: true, capture_pageleave: true, autocapture: true, capture_exceptions: true, session_recording: { maskAllInputs: true } }); } catch (e) {} };
      document.documentElement.appendChild(phs);
    } catch (e) {}
  }
  function ph(name, props) { try { if (window.posthog && window.posthog.capture) window.posthog.capture(name, props || {}); } catch (e) {} }
  function lsGet(k, d) { try { var v = localStorage.getItem(k); return v === null ? d : v; } catch (e) { return d; } }
  function lsSet(k, v) { try { localStorage.setItem(k, v); } catch (e) {} }
  function bestOf() { return parseInt(lsGet(LS_BEST, '0'), 10) || 0; }
  function todayStr() { var n = new Date(); return n.getFullYear() + '-' + ('0' + (n.getMonth() + 1)).slice(-2) + '-' + ('0' + n.getDate()).slice(-2); }
  function todayGame() { return DAILY_GAMES[Math.floor(Date.now() / 86400000) % DAILY_GAMES.length]; }
  function markDaily() {
    var t = todayStr();
    var y = new Date(); y.setDate(y.getDate() - 1);
    var yst = y.getFullYear() + '-' + ('0' + (y.getMonth() + 1)).slice(-2) + '-' + ('0' + y.getDate()).slice(-2);
    var streak = lsGet('arcade_daily_date', '') === yst ? (parseInt(lsGet('arcade_streak', '0'), 10) || 0) + 1 : 1;
    lsSet('arcade_daily_date', t); lsSet('arcade_daily_done', '1'); lsSet('arcade_streak', String(streak));
    ph('daily_completed', { game: GAME, streak: streak });
  }
  function showCTA(on) { if (cta) cta.style.display = on ? 'block' : 'none'; if (hint) hint.style.display = on ? 'none' : 'block'; }
  function wireCTA() {
    if (!cta) return;
    var links = cta.querySelectorAll('a');
    for (var i = 0; i < links.length; i++) {
      links[i].addEventListener('click', function () {
        var href = this.getAttribute('href') || '';
        var channel = href.indexOf('linkedin') !== -1 ? 'linkedin' : (href.indexOf('t.me') !== -1 ? 'telegram' : 'other');
        ph('contact_click', { location: 'game_over', channel: channel, game: GAME });
      });
    }
  }
  // —— /retention ——

  function normcdf(x) {
    var t = 1 / (1 + 0.2316419 * Math.abs(x));
    var d = 0.3989422804014327 * Math.exp(-x*x/2);
    var p = d * t * (0.319381530 + t * (-0.356563782 + t * (1.781477937 + t * (-1.821255978 + t * 1.330274429))));
    return x > 0 ? 1 - p : p;
  }

  function onSig() {
    var taps = Math.round(state.nA / 150);
    var best = bestOf();
    var newBest = best === 0 || taps < best;
    if (newBest) { lsSet(LS_BEST, String(taps)); ph('best_broken', { game: GAME, old_best: best, new_best: taps, score: taps }); }
    var isDaily = todayGame() === GAME && taps <= DAILY_TARGET;
    if (isDaily) markDaily();
    showCTA(newBest || isDaily);
    ph('sig_reached', { game: GAME, taps: taps, new_best: newBest, daily_done: !!isDaily });
  }

  function update() {
    var nA = state.nA, nB = state.nB, xA = state.xA, xB = state.xB;
    var pA = nA ? xA/nA : 0, pB = nB ? xB/nB : 0;
    var p = 1;
    if (nA + nB > 0) {
      var pp = (xA + xB) / (nA + nB);
      var se = Math.sqrt(pp * (1 - pp) * (1/nA + 1/nB));
      if (se > 0) {
        var z = (pA - pB) / se;
        p = 2 * (1 - normcdf(Math.abs(z)));
      }
    }
    p = Math.max(0, Math.min(1, p));
    barA.setAttribute('width', Math.round(pA / 0.4 * 320));
    barB.setAttribute('width', Math.round(pB / 0.4 * 320));
    valA.textContent = (pA * 100).toFixed(1) + '%';
    valB.textContent = (pB * 100).toFixed(1) + '%';
    if (p < 0.05) {
      pval.textContent = '< 0.05';
      pval.setAttribute('fill', '#ff6643');
      if (!state.sig) {
        state.sig = true;
        btnLabel.textContent = 'RESET';
        onSig();
      }
    } else {
      pval.textContent = p.toFixed(3);
      pval.setAttribute('fill', '#f4f4f5');
    }
    var best = bestOf();
    statusT.textContent = 'p = ' + (p < 0.05 ? '< 0.05' : p.toFixed(3)) + ' · n = ' + Math.round(nA) + ' / arm' + (best ? ' · Best: ' + best + ' taps' : '');
  }

  function collect() {
    if (state.sig) { reset(); return; }
    if (!started) { started = true; ph('experiment_started', { game: GAME }); }
    for (var i = 0; i < 150; i++) { if (Math.random() < 0.34) state.xA++; }
    for (var j = 0; j < 150; j++) { if (Math.random() < 0.30) state.xB++; }
    state.nA += 150; state.nB += 150;
    update();
  }

  function reset() {
    state = {nA:0, xA:0, nB:0, xB:0, sig:false};
    started = false;
    btnLabel.textContent = 'COLLECT DATA';
    showCTA(false);
    update();
  }

  document.addEventListener('click', function (e) {
    var t = e.target;
    if (t && t.closest && t.closest('a')) return;
    collect();
  });
  document.addEventListener('keydown', function (e) {
    if (e.key === ' ' || e.key === 'Enter') collect();
  });

  wireCTA();
  update();
})();
